    const MAP_BOUNDS = {west:102, east:108, north:15, south:10};
    const mercator = lat => Math.log(Math.tan(Math.PI / 4 + lat * Math.PI / 360));
    const mapPosition = (lat, lon) => `left:${((lon - MAP_BOUNDS.west) / (MAP_BOUNDS.east - MAP_BOUNDS.west) * 100).toFixed(2)}%;top:${((mercator(MAP_BOUNDS.north) - mercator(lat)) / (mercator(MAP_BOUNDS.north) - mercator(MAP_BOUNDS.south)) * 100).toFixed(2)}%`;
    const MAP_LABELS = [['mapCambodia','main',12.75,105.3],['mapThailand','',14.55,102.75],['mapLaos','',14.82,106.45],['mapVietnam','',11.25,107.3],['mapGulf','water',10.8,102.72],['mapTonleSap','water',12.98,103.98]];
    function renderMap(){return `<section class="card map-panel"><div class="map-header"><h3>${esc(t('cityOverview'))}</h3><span class="pill">${FACILITIES.length} ${esc(t('centres'))}</span></div><div class="map-real photo ph-map" role="group" aria-label="${esc(t('cityOverview'))}">${MAP_LABELS.map(([key,kind,lat,lon])=>`<span class="map-label ${kind}" style="${mapPosition(lat,lon)}" aria-hidden="true">${esc(t(key))}</span>`).join('')}${FACILITIES.map(f=>`<button class="map-pin ${selectedFacility===f.id?'active':''}" style="${mapPosition(f.lat,f.lon)}" data-action="map-pin" data-id="${f.id}" aria-label="${esc(tr(f.name))}"><span class="pin-dot"></span><span class="pin-label">${esc(t(f.city))}</span></button>`).join('')}<span class="map-attrib">${esc(t('mapCredit'))}</span></div><div class="map-footer"><p class="tiny muted" style="margin-bottom:8px">${esc(t('mapExplanation'))}</p><a class="btn btn-text btn-small" href="https://www.openstreetmap.org/#map=7/12.3/104.8" target="_blank" rel="noopener noreferrer">${icon('external')}${esc(t('liveMap'))}</a></div></section>`;}
    function facilityCard(f){const saved=state.savedFacilities.includes(f.id);return `<article class="card facility-card ${selectedFacility===f.id?'selected':''}" id="facility-${f.id}">${photo(f.id,'facility-media')}<span class="pill on-photo">${icon('pin')}${esc(t(f.city))}</span><button class="bookmark on-photo media-action ${saved?'saved':''}" data-action="save-facility" data-id="${f.id}" aria-label="${esc(t('saveFacility'))}" aria-pressed="${saved}">${icon('bookmark')}</button><div class="facility-body"><h3>${esc(tr(f.name))}</h3><p>${esc(tr(f.address))}</p><div class="service-tags">${f.services.map(s=>`<span class="pill blue">${esc(t(s))}</span>`).join('')}</div><p class="tiny hours">${icon('clock')}<span>${esc(tr(f.hours))}</span></p><div class="row wrap"><a class="btn btn-primary btn-small" href="tel:${f.phone}">${icon('phone')}${esc(t('call'))}</a><a class="btn btn-light btn-small" href="https://www.google.com/maps/search/?api=1&amp;query=${encodeURIComponent(f.query)}" target="_blank" rel="noopener noreferrer">${icon('map')}${esc(t('directions'))}</a></div><div class="verification"><span>${esc(f.displayPhone)}</span><span>${esc(t('checked'))}: ${esc(formatDate(CHECKED))}</span><span><a href="${f.url}" target="_blank" rel="noopener noreferrer">${esc(t('officialWebsite'))}${icon('external')}</a>${f.serviceUrl?` · <a href="${f.serviceUrl}" target="_blank" rel="noopener noreferrer">${esc(t('allServices'))}${icon('external')}</a>`:''}</span></div></div></article>`;}
    function facilityResults(){const f=filters.centres;const q=f.query.trim().toLocaleLowerCase();return FACILITIES.filter(v=>(f.city==='all'||v.city===f.city)&&(f.service==='all'||v.services.includes(f.service))&&(!f.saved||state.savedFacilities.includes(v.id))&&(!q||[...v.name,...v.address,t(v.city),v.short].join(' ').toLocaleLowerCase().includes(q)));}
    function facilityResultsMarkup(){const list=facilityResults();return list.length?list.map(facilityCard).join(''):empty('noResults','noResultsSub','map',button('clearFilters','clear-filters','data-kind="centres"','btn-soft'));}
    function renderCentres(){const f=filters.centres;return pageHead('centresTitle','centresSub')+notice('facilityNotice','warning')+`<div class="toolbar">${search('centres','searchCentres')}<div class="row wrap"><label><span class="screen-reader">${esc(t('allCities'))}</span><select class="filter" data-select="city">${['all','phnompenh','siemreap','kampot'].map(k=>`<option value="${k}" ${f.city===k?'selected':''}>${esc(t(k==='all'?'allCities':k))}</option>`).join('')}</select></label><label><span class="screen-reader">${esc(t('allServices'))}</span><select class="filter" data-select="service">${['all','maternal','children','general'].map(k=>`<option value="${k}" ${f.service===k?'selected':''}>${esc(t(k==='all'?'allServices':k))}</option>`).join('')}</select></label><button class="filter ${f.saved?'active':''}" data-action="saved-facilities" aria-pressed="${f.saved}">${esc(t('savedOnly'))}</button></div></div><div class="map-layout">${renderMap()}<div class="facility-list" id="centres-results">${facilityResultsMarkup()}</div></div>`;}
    function newsResults(){const f=filters.news;const q=f.query.trim().toLocaleLowerCase();return STORIES.filter(s=>(f.category==='all'||(f.category==='saved'?state.savedStories.includes(s.id):s.category===f.category))&&(!q||[...s.title,...s.summary,s.publisher].join(' ').toLocaleLowerCase().includes(q)));}
    function storyCard(s,lead=false){const saved=state.savedStories.includes(s.id);return `<article class="article-card${lead?' is-lead':''}">${photo(s.id,'article-cover')}<div class="article-body"><p class="meta"><strong>${esc(s.publisher)}</strong><span>${s.date?esc(formatDate(s.date)):`${esc(t('checked'))}: ${esc(formatDate(CHECKED))}`}</span><span>${esc(t(s.category))}</span></p><h3><a href="${s.url}" target="_blank" rel="noopener noreferrer">${esc(tr(s.title))}</a></h3><p class="summary">${esc(tr(s.summary))}</p><div class="article-actions">${lead?`<a class="text-link" href="${s.url}" target="_blank" rel="noopener noreferrer">${esc(t('openArticle'))}${icon('external')}</a>`:''}${renderAudioPlayer(s,'article-'+s.id)}${shareActions('article',tr(s.title),s.url)}<button class="bookmark ${saved?'saved':''}" data-action="save-story" data-id="${s.id}" aria-label="${esc(t('bookmarkStory'))}" aria-pressed="${saved}">${icon('bookmark')}</button></div></div></article>`;}
    function newsResultsMarkup(){const list=newsResults();return list.length?list.map(s=>storyCard(s)).join(''):empty('noResults','noResultsSub','news',button('clearFilters','clear-filters','data-kind="news"','btn-soft'));}
    function renderNews(){return pageHead('newsTitle','newsSub')+notice('newsNotice')+`<div class="toolbar">${search('news','searchNews')}${categoryButtons('news',['all','health','hygiene','climate','women','saved'])}</div><div class="article-grid" id="news-results">${newsResultsMarkup()}</div>`;}
    const statusText = status => t(status==='completed'?'completedStatus':status);
    function appointmentCard(a){const d=appointmentDate(a);const late=['upcoming','rescheduled'].includes(a.status)&&d<new Date();return `<article class="card appointment-card"><div class="date-box"><strong>${esc(formatDate(d,{day:'numeric'}))}</strong><small>${esc(formatDate(d,{month:'short'}))}</small></div><div class="appointment-main"><span class="pill ${late||a.status==='missed'?'orange':''}">${esc(late?t('overdue'):statusText(a.status))}</span><h3>${esc(a.title)}</h3><p>${icon('clock')} ${esc(formatDate(d))} · ${esc(formatTime(d))} (UTC+7)</p><p>${icon('pin')} ${esc(facilityName(a))}</p>${a.notes?`<p class="appointment-notes">${esc(a.notes)}</p>`:''}<div class="appointment-actions"><label><span class="screen-reader">${esc(t('statusLabel'))}</span><select data-status="${esc(a.id)}">${STATUSES.map(s=>`<option value="${s}" ${s===a.status?'selected':''}>${esc(statusText(s))}</option>`).join('')}</select></label>${button('edit','edit-appointment',`data-id="${esc(a.id)}"`,'btn-light btn-small','edit')}${button('exportCalendar','calendar',`data-id="${esc(a.id)}"`,'btn-soft btn-small','download')}<button class="btn btn-danger btn-small" data-action="delete-appointment" data-id="${esc(a.id)}" aria-label="${esc(t('delete'))}">${icon('trash')}</button></div></div></article>`;}
    function appointmentResultsMarkup(){const category=filters.appointments.category;const list=state.appointments.filter(a=>category==='all'||(category==='upcoming'?['upcoming','rescheduled'].includes(a.status):a.status===category)).sort((a,b)=>appointmentDate(a)-appointmentDate(b));return list.length?list.map(appointmentCard).join(''):empty('noAppointments','noAppointmentsSub','calendar',button('addAppointment','new-appointment','','btn-primary','plus'));}
    function notificationsButton(){const enabled='Notification' in window&&Notification.permission==='granted';return button(enabled?'alertsEnabled':'allowAlerts','notifications','','btn-soft','bell');}
