    function renderSettings(){const completed=LESSONS.filter(isComplete).length;const attempts=Object.values(state.progress).reduce((sum,p)=>sum+p.attempts,0);return pageHead('settingsTitle','settingsSub')+`<div class="settings-grid"><section class="card"><div class="row between"><h2 style="margin:0">${esc(t('offlineAccess'))}</h2><span class="tile-icon">${icon('download')}</span></div><p style="margin-top:18px">${esc(t(location.protocol==='file:'?'localFilesReady':offlineCached?'cachedReady':'cachePending'))}</p><div class="checkline">${icon('check')}${esc(t('bundled'))}</div><div class="checkline">${icon('check')}${esc(t('offlineAppointments'))}</div><div class="checkline">${icon('check')}${esc(t('offlineDirectory'))}</div><p class="tiny" style="margin-top:15px">${esc(t('needsInternet'))}</p>${notificationsButton()}<p class="tiny" style="margin:9px 0 0">${esc(t('alertClosed'))}</p></section><section class="card"><div class="row between"><h2 style="margin:0">${esc(t('backupTitle'))}</h2><span class="tile-icon blue">${icon('lock')}</span></div><p style="margin-top:18px">${esc(t('backupDescription'))}</p><div class="info-grid"><div><strong>${completed}</strong><small>${esc(t('lessonsDone'))}</small></div><div><strong>${state.appointments.length}</strong><small>${esc(t('appointments'))}</small></div><div><strong>${attempts}</strong><small>${esc(t('totalAttempts'))}</small></div></div><div class="row wrap">${button('exportBackup','export-backup','','btn-primary','download')}${button('restoreBackup','restore-backup','','btn-light','upload')}</div>${corruptRaw?`<div style="margin-top:13px">${button('downloadOriginal','export-original','','btn-light','download')}</div>`:''}<div class="divider"></div>${button('clearData','clear-data','','btn-danger','trash')}</section><section class="card"><h2>${esc(t('aboutTitle'))}</h2><p>${esc(t('aboutText'))}</p><details open><summary>${esc(t('healthScope'))}</summary><p>${esc(t('healthScopeText'))}</p></details><details><summary>${esc(t('howToRun'))}</summary><p>${esc(t('runText'))}</p><p>${esc(t('hostText'))}</p><div class="code">python3 -m http.server 8000</div></details><details><summary>${esc(t('phoneHelp'))}</summary><p>${esc(t('phoneText'))}</p></details><p class="source-date" style="margin-top:15px">Sokha v1.0.0 · HTML / JavaScript · ${esc(t('timezone'))}</p></section><section class="card"><h2>${esc(t('sourcesTitle'))}</h2><p>${esc(t('sourcesText'))}</p><div class="source-list"><a href="https://www.who.int/health-topics/water-sanitation-and-hygiene-WASH" target="_blank" rel="noopener noreferrer">${icon('external')}WHO · Water, sanitation and hygiene</a><a href="https://www.unicef.org/cambodia/water-sanitation-and-hygiene" target="_blank" rel="noopener noreferrer">${icon('external')}UNICEF Cambodia · WASH</a><a href="https://www.wateraid.org/global/our-work/where-we-work/cambodia" target="_blank" rel="noopener noreferrer">${icon('external')}WaterAid · Cambodia</a><a href="https://nmchc.gov.kh/" target="_blank" rel="noopener noreferrer">${icon('external')}NMCHC · Cambodia</a><a href="https://www.cdc.gov/global-water-sanitation-hygiene/about/about-safe-water-storage.html" target="_blank" rel="noopener noreferrer">${icon('external')}CDC · Safe water storage</a></div><div class="divider"></div><h3>${esc(t('latestSources'))}</h3><div class="source-list"><a href="https://www.who.int/news" target="_blank" rel="noopener noreferrer">${icon('external')}WHO · News</a><a href="https://www.wateraid.org/global/our-work/news-stories" target="_blank" rel="noopener noreferrer">${icon('external')}WaterAid · News & stories</a></div><div class="divider"></div><h3>${esc(t('photoCredits'))}</h3><p class="tiny">${esc(t('photoNote'))}</p><div class="source-list">${photoSources().map(([credit,url])=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${icon('external')}${esc(credit)} · ${esc(new URL(url).hostname.replace(/^www\./,''))}</a>`).join('')}</div></section></div>`;}
    const fillIn=(template,values)=>template.replace(/\{(\w+)\}/g,(_,key)=>values[key]??'');
    const campaignStart=c=>new Date(`${c.date}T${c.time}:00+07:00`);
    const optionName=(list,id)=>tr(list.find(item=>item.id===id)?.name||pair('',''));
