      const when=[line('msgDateLine'),line('msgPlaceLine')];
      const lines=kind==='volunteers'?[line('msgVolunteersHead'),...when,line('msgVolunteersCount',c.volunteers>0),line('msgRolesLine',c.roles.length>0),'',line('msgVolunteersBody'),line('msgJoinLine',!!c.contact)]
        :kind==='donations'?[line('msgDonationsHead'),...when,line('msgNeedsLine',!!v.items),'',line('msgDonationsBody'),line('msgContactLine',!!c.contact)]
        :[line('msgSessionLine'),...when,'',line('msgInviteBody'),line('msgContactLine',!!c.contact)];
