        <section class="land-outreach" id="land-community"><div class="land-wrap outreach-grid"><div class="outreach-copy">${intro('landCommunityEyebrow','landCommunityTitle','landCommunityText')}<ol class="outreach-steps">${JOIN.map(j=>`<li><span class="tile-icon ${j.tone}">${icon(j.symbol)}</span><div><strong>${esc(t(j.title))}</strong><span>${esc(t(j.text))}</span><button class="link-button" data-action="join-details" data-role="${j.id}">${esc(t('seeDetails'))}${icon('arrow')}</button></div></li>`).join('')}</ol><div class="hero-ctas"><button class="btn btn-primary btn-lg" data-action="register" data-role="volunteer">${icon('check')}${esc(t('registerNow'))}</button><a class="btn btn-light btn-lg" href="#community">${esc(t('openToolkit'))}${icon('arrow')}</a></div></div><div class="outreach-media">${photo('safe-water','outreach-main')}${photo('school','outreach-small',false)}<span class="outreach-badge">${icon('clock')}${esc(t('sessionPlanTitle'))}</span></div></div></section>
